function respond(request:MockSecureTransportControl["requests"][number],payload:Uint8Array):void{request.callbacks.onSecureConnected({address:request.options.pinnedAddress,family:request.options.family,hostnameVerified:true,authorized:true,authorizationError:null});request.callbacks.onResponse(200,"1.1",["content-length",String(payload.byteLength),"content-type","application/json"]);request.callbacks.onData(payload);request.callbacks.onEnd();}
async function waitForRequests(mock:MockSecureTransportControl,count:number):Promise<void>{for(let turn=0;turn<2_000&&mock.requests.length<count;turn++)await Promise.resolve();expect(mock.requests).toHaveLength(count);}
function fakeScheduler(){let now=0,next=0;const callbacks=new Map<number,()=>void>(),deadlines=new Map<number,number>(),milliseconds=new Map<number,number>(),cleared:number[]=[];return{capability:createInvocationSchedulerCapabilitiesInternal({monotonicNow:()=>now,setTimeout:(callback,delay)=>{const id=++next;callbacks.set(id,callback);deadlines.set(id,now+delay);milliseconds.set(id,delay);return id;},clearTimeout:id=>{cleared.push(id as number);callbacks.delete(id as number);deadlines.delete(id as number);milliseconds.delete(id as number);}}),advance(ms:number){now+=ms;for(const [id,callback] of [...callbacks])if(deadlines.get(id)!<=now){callbacks.delete(id);deadlines.delete(id);milliseconds.delete(id);callback();}},callbacks,milliseconds,cleared};}
function dependencies(overrides:Partial<Record<"createTransport"|"createCrossref"|"createOpenalex"|"createPubmed"|"createPmc"|"createScheduler",(...args:any[])=>unknown>>={}){const mocks:MockSecureTransportControl[]=[],schedulers:ReturnType<typeof fakeScheduler>[]=[],seen:unknown[]=[];const descriptor={createTransport:(options:any)=>{seen.push(options);if(overrides.createTransport)return overrides.createTransport(options);const mock=createMockSecureTransportCapabilities(),node=createNodeRuntimeCapabilitiesInternal(mock.ops);mocks.push(mock);return createSecureJsonTransport(options,createSecureTransportCapabilitiesInternal(createPinnedHopRuntimeInternal(undefined,node),createContentDecodeCapabilitiesInternal({decodeContentLayer:async(_encoding,input)=>new Uint8Array(input)}),createNodeRequestDeadlineSchedulerCapabilitiesInternal(node)));},createCrossref:(options:any)=>{seen.push(options);return overrides.createCrossref?.(options)??createCrossrefAdapter();},createOpenalex:(options:any)=>{seen.push(options);return overrides.createOpenalex?.(options)??createOpenAlexAdapter();},createPubmed:(options:any)=>{seen.push(options);return overrides.createPubmed?.(options)??createPubmedAdapter();},createPmc:(options:any)=>{seen.push(options);return overrides.createPmc?.(options)??createPmcAdapter();},createScheduler:(options:any)=>{seen.push(options);if(overrides.createScheduler)return overrides.createScheduler(options);const scheduler=fakeScheduler();schedulers.push(scheduler);return scheduler.capability;}};return{factory:createAcademicAcquisitionDependencyFactoryInternal(descriptor as never),mocks,schedulers,seen};}
async function drive<T>(promise:Promise<T>,mocks:readonly MockSecureTransportControl[],select:(url:string,index:number)=>Uint8Array=bodyFor):Promise<T>{let settled=false;void promise.finally(()=>{settled=true;}).catch(()=>{});const answered=new Set<object>();for(let turn=0;turn<2_000&&!settled;turn++){for(const mock of mocks)for(const request of mock.requests)if(!answered.has(request)){answered.add(request);const payload=select(request.options.url,answered.size-1);respond(request,payload);}await Promise.resolve();}return promise;}
